func Iso_ObjHash(pIso *Iso_Obj_t, nBins int32) int32 {

    var pArray *uint32  = (unsigned *)pIso;
    var i, Value uint32;
    assert(ISO_NUM_INTS < 8, "ISO_NUM_INTS < 8");
    for  i = 0; i < ISO_NUM_INTS; i++  {
        Value ^= spStatic_Iso_ObjHash_BigPrimes[i] * pArray[i];
    }
    return Value % nBins;
}

